import json,re
from pathlib import Path
P=Path(__file__).resolve().parent
sources=[];receipts=[]
for fn in ('root_receipts.json','root_followups.json','root_details.json','root_coverage.json'):
 if not (P/fn).exists():continue
 for i,r in enumerate(json.loads((P/fn).read_text())):
  receipts.append(dict(file=fn,record=i,**r));rs=r.get('result',r)
  for m in rs.get('structuredContent',{}).get('messages',[]) or rs.get('content',[]):
   for line in m.get('content',m.get('text','')).splitlines():
    if line.startswith(('- [','[USER_','[PRIOR_')):sources.append((fn,i,line))
E=[]
def add(n,anchor,title,field,question,summary,defs,name,statement,proof,setup,calculation,conclusion,limits,extension,refs=(),evidence=None):
 s=next(s for s in sources if anchor in s[2]);d=re.search(r'([UA])@(2025-07-\d\d)',s[2]);ev=evidence or (d.group(1) if d else 'T');date=d.group(2) if d else None
 E.append(dict(id=f'Y25-07-{n:03d}',title=title,status='Developed classical mathematics with explicit hypotheses and scoped evidence',summary=summary,definitions=defs,result=dict(name=name,statement=statement,proof=proof),example=dict(setup=setup,calculation=calculation,conclusion=conclusion),limits=limits,extension=extension,references=[dict(label=x,url=y) for x,y in refs],original=dict(date=date,month='2025-07',evidence=ev,field=field,concept=title,origin='Dated historical retrieval; see exact source line',question=question,math=statement,finish='Proof, worked example and explicit remaining problem',kind='Revised mathematical treatment',refs=[y for x,y in refs],source_excerpt=s[2],retrieval_receipt=f'{s[0]} record {s[1]}',original_question=None,attribution_note='The excerpt is an exact retrieval-result line, usually a historical paraphrase rather than a verbatim original prompt. User-attributed topics and assistant assertions remain distinct. The revised question, classical proof and example are newly authored; absent history and novelty are not claimed.')))
EC=('Milne, Elliptic Curves','https://www.jmilne.org/math/Books/EC2.pdf')
ANT=('Milne, Algebraic Number Theory','https://www.jmilne.org/math/CourseNotes/ANT.pdf')
